head.script:
scwin.onpageload = function() {
    //dataList1.insertRow();
    dataList2.insertRow();
    dataList2.insertRow();
    var row = dataList1.getRowJSON(0);
    var json = [];
    for (var i = 0; i < 50; i++) {
        var tmp = {};
        for (var item in row) {
            if (item == "rowStatus") continue;
            if (item == "col1") tmp[item] = 0;
            else tmp[item] = item + "_" + i;
            //tmp[item] =i%11==0?"\u001a":item+"_"+i;
            //if(item == "col2") tmp[item] = "N"
            //if(item == "depth") tmp[item] = i%5==0 ? 1 : i%5;
        }
        json.push(tmp);
    }
    dataList1.setJSON(json);
    dataList2.setJSON([{
            "col1": "col1",
            "col2": "col2",
            "col3": "col3",
            "col4": "col4"
        },
        {
            "col1": "col1",
            "col2": "col2",
            "col3": "col3",
            "col4": "col4"
        },
        {
            "col1": "col1",
            "col2": "col2",
            "col3": "col3",
            "col4": "col4"
        },
        {
            "col1": "col1",
            "col2": "col2",
            "col3": "col3",
            "col4": "col4"
        },
    ]);
    $p.js("/hotfix/hotfix_WEFF_923.js");
};
scwin.onpageunload = function() {};
